  p.line {
    margin: 4px 0;
    font-size: 15px;
    line-height: 1.7;
  }

  .indent {
    margin-left: 18px;
  }

  .divider {
    border-top: 1px solid rgba(122,43,32,0.4);
    margin: 10px 0;
